using System;
using System.Linq;
using NUnit.Framework;
using CashflowChains.Domain;
using LocalGame.Data;
public class CampaignTests {
 [Test] public void All72ReferenceNetworksAreFreeLegalAndThreeStar(){for(int i=0;i<72;i++){var m=Campaign.Get(i);m.Start.Validate();m.Solution.Validate();var run=new CityRun(i,m.Solution.Copy());var result=run.Preview();Assert.IsTrue(result.Conserved(),"level "+i);Assert.AreEqual(3,run.Stars(result.Credits),"level "+i);Assert.Greater(result.Credits,0);Assert.AreEqual(result.Credits,result.Events.Sum(e=>e.Credits));}}
 [Test] public void RewardReplaysNeverFarmCredits(){var p=new Profile();for(int i=0;i<72;i++){var m=Campaign.Get(i);new CityRun(i,m.Solution.Copy()).Activate(p,"a"+i);new CityRun(i,m.Solution.Copy()).Activate(p,"b"+i);}Assert.AreEqual(216,p.TotalStars);Assert.AreEqual(21950,p.Credits);Profile.Validate(p);}
 [Test] public void BlockedTilesRejectMovementAndPreviewIsPure(){var m=Campaign.Get(48);var run=new CityRun(48);string before=run.Board.Fingerprint();run.Preview();Assert.AreEqual(before,run.Board.Fingerprint());for(int cell=0;cell<36;cell++)if((m.Start.Blocked&(1UL<<cell))!=0)Assert.False(run.Move(1,cell%6,cell/6));}
 [Test] public void PortCostsAreInTheMoneyLedger(){var b=new Board{Width=2,Height=1,Budget=1000};b.Nodes.Add(new Node(1,"port",0,0));var r=Resolver.Run(b);Assert.AreEqual(-64,r.Credits);Assert.AreEqual(-64,r.Events.Sum(e=>e.Credits));Assert.True(r.Conserved());}
 [Test] public void ProfileRejectsForgedCurrencyAndMalformedStars(){var p=new Profile();p.Credits++;Assert.Throws<ArgumentException>(()=>Profile.Validate(p));p=new Profile{Stars=new int[2]};Assert.Throws<ArgumentException>(()=>Profile.Validate(p));}
 [Test] public void All24BuildingRecipesAreNormalized(){Assert.AreEqual(24,Pieces.All.Length);Assert.AreEqual(24,Pieces.All.Select(p=>p.Id).Distinct().Count());foreach(var p in Pieces.All){Assert.AreEqual(3,p.Need.Length);Assert.AreEqual(3,p.Make.Length);Assert.GreaterOrEqual(p.Price,0);for(int r=0;r<4;r++)Assert.LessOrEqual(Pieces.Ports(p.Outputs,r),15);}}
}
public class ContractTests {
 [NUnit.Framework.Test] public void OfflineContractReturnsExactlyOnceAndClockRollbackCannotCollect(){var profile=new LocalGame.Data.Profile();var mission=CashflowChains.Domain.Campaign.Get(0);var run=new CashflowChains.Domain.CityRun(0,mission.Solution.Copy());run.Activate(profile,"clear");var routes=new System.Collections.Generic.List<CashflowChains.Domain.RouteContract>();long start=System.DateTime.UtcNow.Ticks;NUnit.Framework.Assert.True(CashflowChains.Domain.ContractDesk.Send(routes,0,run,profile,start));NUnit.Framework.Assert.False(CashflowChains.Domain.ContractDesk.Claim(routes[0],profile,start-1));NUnit.Framework.Assert.False(CashflowChains.Domain.ContractDesk.Claim(routes[0],profile,start));NUnit.Framework.Assert.True(CashflowChains.Domain.ContractDesk.Claim(routes[0],profile,start+System.TimeSpan.FromMinutes(1).Ticks));long wallet=profile.Credits;NUnit.Framework.Assert.False(CashflowChains.Domain.ContractDesk.Claim(routes[0],profile,start+System.TimeSpan.FromDays(1).Ticks));NUnit.Framework.Assert.AreEqual(wallet,profile.Credits);LocalGame.Data.Profile.Validate(profile);CashflowChains.Domain.ContractDesk.Validate(routes);}
 [NUnit.Framework.Test] public void DailyUsesUtcCalendarAndCertified72Pool(){for(int i=0;i<10000;i++){var day=new System.DateTime(2026,1,1,0,0,0,System.DateTimeKind.Utc).AddDays(i);int level=LocalGame.Data.DailyPuzzle.Level(day);NUnit.Framework.Assert.That(level,NUnit.Framework.Is.InRange(0,71));NUnit.Framework.Assert.AreEqual(level,LocalGame.Data.DailyPuzzle.Level(day.AddHours(23)));}}
}
public class ProductionRoutingTests {
 [NUnit.Framework.Test] public void EveryBuildingAppearsInTheFreeCampaign(){var seen=new System.Collections.Generic.HashSet<string>();for(int i=0;i<72;i++)foreach(var n in CashflowChains.Domain.Campaign.Get(i).Solution.Nodes)seen.Add(n.Kind);NUnit.Framework.Assert.AreEqual(24,seen.Count,string.Join(",",seen));}

 [NUnit.Framework.Test] public void FactoryForkFeedsBothLegalCashOutlets(){var m=CashflowChains.Domain.Campaign.Get(28);var r=CashflowChains.Domain.Resolver.Run(m.Solution);NUnit.Framework.Assert.GreaterOrEqual(r.Events.Where(e=>e.Reason=="sale").Select(e=>e.Source).Distinct().Count(),2);}
 [NUnit.Framework.Test] public void AllEightCombosCanActuallyBeDemonstrated(){var combos=new System.Collections.Generic.HashSet<string>();for(int i=0;i<72;i++){var m=CashflowChains.Domain.Campaign.Get(i);foreach(var combo in CashflowChains.Domain.Campaign.Combos(m.Solution,CashflowChains.Domain.Resolver.Run(m.Solution,m.Multiplier)))combos.Add(combo);}NUnit.Framework.Assert.AreEqual(8,combos.Count,string.Join(",",combos));}
}
public class DraftBudgetTests {
 [Test] public void BuildAndReturnCycleNeverCreatesBudgetOrCityCredits(){var profile=new LocalGame.Data.Profile();var run=new CashflowChains.Domain.CityRun(0);int spent=run.Spent;long wallet=profile.Credits;for(int i=0;i<1000;i++){NUnit.Framework.Assert.True(run.Place("farm",0,0));int id=run.Board.Nodes.Max(n=>n.Id);NUnit.Framework.Assert.AreEqual(spent+60,run.Spent);NUnit.Framework.Assert.True(run.Remove(id));NUnit.Framework.Assert.AreEqual(spent,run.Spent);}NUnit.Framework.Assert.AreEqual(wallet,profile.Credits);new CashflowChains.Domain.CityRun(0,run.Board.Copy());}
 [Test] public void PlacementValidatesBudgetStocksRosterAndFreeUndo(){var run=new CashflowChains.Domain.CityRun(0);NUnit.Framework.Assert.False(run.Place("stadium",0,0));NUnit.Framework.Assert.True(run.Place("farm",0,0,3));NUnit.Framework.Assert.AreEqual(1,run.Board.Nodes.Last().InitialEnergy);NUnit.Framework.Assert.True(run.Undo());NUnit.Framework.Assert.AreEqual(2,run.Board.Nodes.Count);var forged=run.Board.Copy();forged.Nodes[0].InitialGoods=64;NUnit.Framework.Assert.Throws<System.ArgumentException>(()=>new CashflowChains.Domain.CityRun(0,forged));}
 [Test] public void EmptyEditableLayoutIsValidAndCannotEarnMoney(){var run=new CashflowChains.Domain.CityRun(0);foreach(var node in run.Board.Nodes.ToArray())run.Remove(node.Id);NUnit.Framework.Assert.AreEqual(0,run.Preview().Credits);new CashflowChains.Domain.CityRun(0,run.Board.Copy());NUnit.Framework.Assert.True(run.Place("cafe",0,0));NUnit.Framework.Assert.AreEqual(0,run.Board.Nodes[0].InitialGoods);}
}
public class SoftPurchaseTests {
 [NUnit.Framework.Test] public void BlueprintSlotsSpendOnlyEarnedCityCreditsAndNeverOverdraw(){var p=new LocalGame.Data.Profile();NUnit.Framework.Assert.False(p.BuyBlueprintSlot());var m=CashflowChains.Domain.Campaign.Get(0);new CashflowChains.Domain.CityRun(0,m.Solution.Copy()).Activate(p,"clear-for-slot");NUnit.Framework.Assert.True(p.BuyBlueprintSlot());NUnit.Framework.Assert.AreEqual(150,p.Credits);NUnit.Framework.Assert.AreEqual(3,p.BlueprintCapacity);NUnit.Framework.Assert.False(p.BuyBlueprintSlot());NUnit.Framework.Assert.AreEqual(150,p.Credits);LocalGame.Data.Profile.Validate(p);}
 [NUnit.Framework.Test] public void EarnedStylePurchaseIsIdempotentAndDoesNotChangePuzzleRewards(){var p=new LocalGame.Data.Profile();p.Grant("fixture-domain-only",500);NUnit.Framework.Assert.True(p.BuyStyle(1));NUnit.Framework.Assert.AreEqual(100,p.Credits);NUnit.Framework.Assert.False(p.BuyStyle(1));p.SetTheme(1);LocalGame.Data.Profile.Validate(p);NUnit.Framework.Assert.AreEqual(0,p.TotalStars);}
}
